/// The full stylesheet for light or dark: colour definitions, then style.css.
pub fn css(dark: bool) -> String {
    let roles = if dark { DARK } else { LIGHT };
    let mut css: String = roles
        .iter()
        .map(|(role, hex)| format!("@define-color {role} {hex};\n"))
        .collect();
    css.push_str(STYLE);
    css
}

/// Dark or light from the desktop: GSettings first, then the GTK theme.
/// (The XDG Desktop Portal, which the Python app asks first, comes in stage 3.)
pub fn desktop_prefers_dark() -> bool {
    let schema = gio::SettingsSchemaSource::default()
        .and_then(|source| source.lookup("org.gnome.desktop.interface", true));
    if let Some(schema) = schema {
        if schema.has_key("color-scheme") {
            let settings = gio::Settings::new("org.gnome.desktop.interface");
            match settings.string("color-scheme").as_str() {
                "prefer-dark" => return true,
                "prefer-light" => return false,
                _ => {}
            }
        }
    }
    let Some(settings) = gtk::Settings::default() else {
        return false;
    };
    if settings.is_gtk_application_prefer_dark_theme() {
        return true;
    }
    settings
        .gtk_theme_name()
        .is_some_and(|name| name.to_lowercase().contains("dark"))
}

/// Applies the palette to the whole app and keeps GTK's own dark flag in step.
pub struct Theme {
    provider: gtk::CssProvider,
    /// Read before the app sets GTK's dark flag, which would otherwise be
    /// read back as the desktop's choice.
    desktop_dark: bool,
}

impl Theme {
    pub fn install() -> Self {
        let provider = gtk::CssProvider::new();
        if let Some(display) = gdk::Display::default() {
            gtk::style_context_add_provider_for_display(
                &display,
                &provider,
                gtk::STYLE_PROVIDER_PRIORITY_APPLICATION,
            );
        }
        Theme {
            provider,
            desktop_dark: desktop_prefers_dark(),
        }
    }

    /// `theme` is the setting: "system", "light" or "dark".
    pub fn apply(&self, theme: &str) -> bool {
        let dark = match theme {
            "dark" => true,
            "light" => false,
            _ => self.desktop_dark,
        };
        #[allow(deprecated)] // load_from_string needs GTK 4.12
        self.provider.load_from_data(&css(dark));
        if let Some(settings) = gtk::Settings::default() {
            if settings.is_gtk_application_prefer_dark_theme() != dark {
                settings.set_gtk_application_prefer_dark_theme(dark);
            }
        }
        dark
    }
}
